package com.rulecraft.decisionops.simulation;

import static org.assertj.core.api.Assertions.*;
import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.ExpressionCommand;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.projects.domain.ProjectRole;import com.rulecraft.decisionops.simulation.RegressionMatrixService.*;import com.rulecraft.decisionops.simulation.domain.*;import com.rulecraft.decisionops.simulation.persistence.RegressionMatrixRunRepository;import com.rulecraft.decisionops.tests.DecisionTestService;import com.rulecraft.decisionops.tests.DecisionTestService.TestCaseCommand;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.crypto.password.PasswordEncoder;import tools.jackson.databind.ObjectMapper;

@SpringBootTest
class RegressionMatrixIntegrationTest {
    @Autowired RegressionMatrixService matrices;@Autowired RegressionMatrixRunRepository matrixRuns;@Autowired DecisionTestService decisionTests;@Autowired DecisionExpressionService expressions;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwordEncoder;@Autowired Clock clock;@Autowired ObjectMapper mapper;@Autowired JdbcClient jdbc;RuleCraftPrincipal admin;
    @BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}

    @Test void executesBoundedMatrixWithImmutableAggregateEvidenceAndIdempotentRetry(){var fixture=fixture();var pass=create(fixture,"passCase","Passing case","750","true");var fail=create(fixture,"failCase","Failing case","650","true");var requestId=UUID.randomUUID();var command=new MatrixRunCommand(requestId,List.of(pass,fail));var run=matrices.execute(admin,fixture.projectId(),fixture.serviceId(),command);assertThat(run.run().status()).isEqualTo(MatrixRunStatus.COMPLETED);assertThat(run.run().passedCount()).isEqualTo(1);assertThat(run.run().failedCount()).isEqualTo(1);assertThat(run.run().errorCount()).isZero();assertThat(run.results()).extracting("status").containsExactly(MatrixCaseStatus.PASSED,MatrixCaseStatus.FAILED);assertThat(run.results()).allSatisfy(result->{assertThat(result.graphVersion()).isNotNull();assertThat(result.decisions()).hasSize(1);});var retried=matrices.execute(admin,fixture.projectId(),fixture.serviceId(),command);assertThat(retried.run().id()).isEqualTo(run.run().id());assertThat(jdbc.sql("select count(*) from regression_matrix_run where client_request_id=:id").param("id",requestId).query(Long.class).single()).isEqualTo(1);assertCode("RC-MATRIX-REQUEST-CONFLICT",()->matrices.execute(admin,fixture.projectId(),fixture.serviceId(),new MatrixRunCommand(requestId,List.of(fail))));}

    @Test void isolatesInvalidCasesAsErrorsAndRejectsUnboundedOrForeignSelections(){var fixture=fixture();var testId=create(fixture,"driftCase","Drift case","700","true");var service=catalog.getService(admin,fixture.projectId(),fixture.serviceId());catalog.updateService(admin,fixture.projectId(),fixture.serviceId(),new DecisionServiceCommand(service.serviceKey(),service.name(),service.description(),List.of(new FieldCommand("score","Score",builtin(BuiltinType.TEXT),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),service.version()));var run=matrices.execute(admin,fixture.projectId(),fixture.serviceId(),new MatrixRunCommand(UUID.randomUUID(),List.of(testId)));assertThat(run.run().status()).isEqualTo(MatrixRunStatus.COMPLETED);assertThat(run.run().errorCount()).isEqualTo(1);assertThat(run.results().getFirst().errorCode()).isEqualTo("RC-TEST-INVALID");assertCode("RC-MATRIX-SELECTION",()->matrices.execute(admin,fixture.projectId(),fixture.serviceId(),new MatrixRunCommand(UUID.randomUUID(),List.of())));assertCode("RC-MATRIX-NOT-FOUND",()->matrices.execute(admin,fixture.projectId(),fixture.serviceId(),new MatrixRunCommand(UUID.randomUUID(),List.of(UUID.randomUUID()))));}

    @Test void viewerCanRunOutsiderCannotDiscoverAndStartupRecoveryInterruptsAbandonedWork(){var fixture=fixture();var testId=create(fixture,"viewerMatrix","Viewer matrix","750","true");var now=Instant.now(clock);var viewerAccount=users.save(new UserAccount(admin.tenantId(),"matrix-viewer"+UUID.randomUUID()+"@example.test","Mira Matrix Viewer",passwordEncoder.encode("CorrectHorseBattery82!"),TenantRole.MEMBER,now));projects.upsertMember(admin,fixture.projectId(),viewerAccount.getId(),ProjectRole.VIEWER);var viewer=new RuleCraftPrincipal(viewerAccount,"acme-rules");assertThat(matrices.execute(viewer,fixture.projectId(),fixture.serviceId(),new MatrixRunCommand(UUID.randomUUID(),List.of(testId))).run().passedCount()).isEqualTo(1);var abandoned=matrixRuns.saveAndFlush(new RegressionMatrixRun(admin.tenantId(),fixture.projectId(),fixture.serviceId(),UUID.randomUUID(),mapper.valueToTree(List.of(testId)).toString(),1,admin.userId(),now));matrices.recoverInterrupted();assertThat(matrixRuns.findById(abandoned.getId()).orElseThrow().getStatus()).isEqualTo(MatrixRunStatus.INTERRUPTED);var outsiderAccount=users.save(new UserAccount(admin.tenantId(),"matrix-outsider"+UUID.randomUUID()+"@example.test","Omar Matrix Outsider",passwordEncoder.encode("CorrectHorseBattery83!"),TenantRole.MEMBER,now));var outsider=new RuleCraftPrincipal(outsiderAccount,"acme-rules");assertCode("RC-PROJECT-NOT-FOUND",()->matrices.list(outsider,fixture.projectId(),fixture.serviceId()));}

    private UUID create(Fixture fixture,String key,String name,String input,String expected){return decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),new TestCaseCommand(null,key,name,null,Map.of("score",mapper.readTree(input)),Map.of("approved",mapper.readTree(expected)))).id();}
    private Fixture fixture(){var project=projects.create(admin,key("P"),"Regression matrices",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Eligibility regression",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"score",BuiltinType.NUMBER);var output=port(GraphPortDirection.OUTPUT,"approved",BuiltinType.BOOLEAN);var serviceInput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.INPUT).findFirst().orElseThrow().ports().getFirst();var serviceOutput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.OUTPUT).findFirst().orElseThrow().ports().getFirst();var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"threshold","Approval threshold",GraphNodeKind.DECISION,null,300,100,List.of(input,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of(edge(serviceInput.id(),input.id()),edge(output.id(),serviceOutput.id()))));var expression=expressions.initialize(admin,project.id(),service.id(),nodeId);expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(expression.version(),"score >= 700"));return new Fixture(project.id(),service.id());}
    private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private PortCommand port(GraphPortDirection direction,String key,BuiltinType type){return new PortCommand(UUID.randomUUID(),direction,key,key,new DecisionGraphService.TypeRefCommand(type,null),true,0);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}private EdgeCommand edge(UUID source,UUID target){return new EdgeCommand(UUID.randomUUID(),source,target);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private void assertCode(String code,Runnable action){assertThatThrownBy(action::run).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo(code);}private record Fixture(UUID projectId,UUID serviceId){}
}
